using Hadron.Erp.Api.Infrastructure;
using Hadron.Erp.Api.Modules.Suppliers.Domain;
using Hadron.Erp.Api.Platform.Audit;
using Microsoft.EntityFrameworkCore;
using Npgsql;

namespace Hadron.Erp.Api.Modules.Suppliers.Application;

public sealed class SupplierService(IDbContextFactory<HadronDbContext> factory, IAuditEventSink auditSink, IHttpContextAccessor accessor, ILogger<SupplierService> logger)
{
    private static readonly string[] Anchors = ["ORDERED", "SHIPPED", "WAREHOUSE_RECEIPT"];
    public async Task<SupplierListResponse> List(string? search, bool includeInactive, Guid? countryId, Guid? ownerId, int page, int pageSize, CancellationToken ct)
    {
        if (page < 1 || pageSize is < 1 or > 100) throw Validation("page", "صفحه معتبر و اندازه ۱ تا ۱۰۰ الزامی است.");
        await using var db = await factory.CreateDbContextAsync(ct); var q = db.Suppliers.AsNoTracking().Where(x => includeInactive || x.IsActive);
        if (countryId.HasValue) q = q.Where(x => x.CountryId == countryId); if (ownerId.HasValue) q = q.Where(x => x.OwnerId == ownerId);
        if (!string.IsNullOrWhiteSpace(search)) { var s = search.Trim(); q = q.Where(x => x.SupplierNumber.Contains(s) || x.Name.Contains(s)); }
        var total = await q.CountAsync(ct);
        var suppliers = await q.OrderBy(x => x.Name).Skip((page - 1) * pageSize).Take(pageSize)
            .Include(x => x.Country).Include(x => x.Owner).Include(x => x.PaymentProfile).ThenInclude(x => x.PaymentTerm)
            .ToListAsync(ct);
        var items = suppliers.Select(x => ToResponse(x, [])).ToList();
        return new(items, page, pageSize, total);
    }
    public async Task<SupplierResponse?> Get(Guid id, CancellationToken ct) { await using var db = await factory.CreateDbContextAsync(ct); return await Load(db, id, ct); }
    public async Task<SupplierMutationResponse> Create(CreateSupplierRequest r, CancellationToken ct)
    {
        ValidateSupplier(r.Name, r.AdvancePercent, r.BeforeShipmentPercent, r.CreditPercent, r.CreditDays, r.CreditAnchor, r.ExpertLeadTimeScore, r.ExpertQualityScore, r.Notes, null, false);
        await using var db = await factory.CreateDbContextAsync(ct); await ValidateReferences(db, r.CountryId, r.OwnerId, r.PaymentTermId, true, true, true, false, ct);
        var supplier = new Supplier(await NextNumber(db, ct), r.Name.Trim(), NormalizeName(r.Name), r.CountryId, r.OwnerId, Clean(r.Notes), r.ExpertLeadTimeScore, r.ExpertQualityScore);
        supplier.PaymentProfile.Set(r.PaymentTermId, r.AdvancePercent, r.BeforeShipmentPercent, r.CreditPercent, r.CreditDays, NormalizeAnchor(r.CreditAnchor));
        db.Add(supplier); await Save(db, ct);
        var response = (await Load(db, supplier.Id, ct))!; var warnings = await Warnings(db, supplier.Id, response.Name, ct); await Emit("Supplier", supplier.Id, "CREATE", response, null, ct); return new(response, warnings);
    }
    public async Task<SupplierMutationResponse> Update(Guid id, UpdateSupplierRequest r, CancellationToken ct)
    {
        await using var db = await factory.CreateDbContextAsync(ct); var s = await Aggregate(db, id, ct); EnsureVersion(s.Version, r.ExpectedVersion);
        ValidateSupplier(r.Name, r.AdvancePercent, r.BeforeShipmentPercent, r.CreditPercent, r.CreditDays, r.CreditAnchor, r.ExpertLeadTimeScore, r.ExpertQualityScore, r.Notes, r.ExpectedVersion, s.IsActive);
        await ValidateReferences(db, r.CountryId, r.OwnerId, r.PaymentTermId, s.CountryId != r.CountryId, s.OwnerId != r.OwnerId, s.PaymentProfile.PaymentTermId != r.PaymentTermId, s.IsActive, ct);
        s.Edit(r.Name.Trim(), NormalizeName(r.Name), r.CountryId, r.OwnerId, Clean(r.Notes), r.ExpertLeadTimeScore, r.ExpertQualityScore); s.PaymentProfile.Set(r.PaymentTermId, r.AdvancePercent, r.BeforeShipmentPercent, r.CreditPercent, r.CreditDays, NormalizeAnchor(r.CreditAnchor));
        await Save(db, ct); var response = (await Load(db, id, ct))!; var warnings = await Warnings(db, id, response.Name, ct); await Emit("Supplier", id, "EDIT", response, null, ct); return new(response, warnings);
    }
    public async Task<SupplierResponse> State(Guid id, bool active, ChangeSupplierStateRequest r, CancellationToken ct)
    {
        if (r.ExpectedVersion < 1) throw Validation("expectedVersion", "نسخه معتبر الزامی است."); await using var db = await factory.CreateDbContextAsync(ct); var s = await Aggregate(db, id, ct); EnsureVersion(s.Version, r.ExpectedVersion);
        if (active) { ValidateSupplier(s.Name, s.PaymentProfile.AdvancePercent, s.PaymentProfile.BeforeShipmentPercent, s.PaymentProfile.CreditPercent, s.PaymentProfile.CreditDays, s.PaymentProfile.CreditAnchor, s.ExpertLeadTimeScore, s.ExpertQualityScore, s.Notes, s.Version, true); await ValidateReferences(db, s.CountryId, s.OwnerId, s.PaymentProfile.PaymentTermId, true, true, true, true, ct); }
        s.ChangeState(active); await Save(db, ct); var response = (await Load(db, id, ct))!; await Emit("Supplier", id, active ? "REACTIVATE" : "DEACTIVATE", response, r.Reason, ct); return response;
    }
    public async Task<IReadOnlyList<PersonResponse>> People(bool includeInactive, CancellationToken ct) { await using var db = await factory.CreateDbContextAsync(ct); return await db.InternalPeople.AsNoTracking().Where(x => includeInactive || x.IsActive).OrderBy(x => x.DisplayNameFa).Select(x => new PersonResponse(x.Id, x.DisplayNameFa, x.DisplayNameEn, x.IsActive, x.Version, x.CreatedAtUtc, x.UpdatedAtUtc)).ToListAsync(ct); }
    public async Task<PersonResponse> CreatePerson(CreatePersonRequest r, CancellationToken ct) { ValidatePerson(r.DisplayNameFa, r.DisplayNameEn, null); await using var db = await factory.CreateDbContextAsync(ct); var p = new InternalPerson(r.DisplayNameFa.Trim(), Clean(r.DisplayNameEn)); db.Add(p); await Save(db, ct); var response = ToPerson(p); await Emit("InternalPerson", p.Id, "CREATE", response, null, ct); return response; }
    public async Task<PersonResponse> UpdatePerson(Guid id, UpdatePersonRequest r, CancellationToken ct) { ValidatePerson(r.DisplayNameFa, r.DisplayNameEn, r.ExpectedVersion); await using var db = await factory.CreateDbContextAsync(ct); var p = await db.InternalPeople.SingleOrDefaultAsync(x => x.Id == id, ct) ?? throw new KeyNotFoundException(); EnsureVersion(p.Version, r.ExpectedVersion); p.Edit(r.DisplayNameFa.Trim(), Clean(r.DisplayNameEn)); await Save(db, ct); var response = ToPerson(p); await Emit("InternalPerson", id, "EDIT", response, null, ct); return response; }
    public async Task<PersonResponse> StatePerson(Guid id, bool active, ChangePersonStateRequest r, CancellationToken ct) { await using var db = await factory.CreateDbContextAsync(ct); var p = await db.InternalPeople.SingleOrDefaultAsync(x => x.Id == id, ct) ?? throw new KeyNotFoundException(); EnsureVersion(p.Version, r.ExpectedVersion); p.ChangeState(active); await Save(db, ct); var response = ToPerson(p); await Emit("InternalPerson", id, active ? "REACTIVATE" : "DEACTIVATE", response, r.Reason, ct); return response; }
    public async Task<SupplierResponse> AddContact(Guid supplierId, ContactRequest r, CancellationToken ct) { ValidateContact(r); await using var db = await factory.CreateDbContextAsync(ct); await using var transaction = await db.Database.BeginTransactionAsync(ct); var s = await Aggregate(db, supplierId, ct); EnsureVersion(s.Version, r.ExpectedVersion); if (r.IsPrimary) ClearPrimary(s); await BumpAggregateVersion(db, s.Id, r.ExpectedVersion, ct); db.Entry(s).State = EntityState.Detached; db.SupplierContacts.Add(new SupplierContact(s.Id, r.FullName.Trim(), Clean(r.JobTitle), Clean(r.Email), Clean(r.Phone), Clean(r.Mobile), r.IsPrimary)); await Save(db, ct); await transaction.CommitAsync(ct); var response = (await Load(db, s.Id, ct))!; await Emit("Supplier", s.Id, "CONTACT_ADD", response, null, ct); return response; }
    public async Task<SupplierResponse> UpdateContact(Guid supplierId, Guid contactId, ContactRequest r, CancellationToken ct) { ValidateContact(r); await using var db = await factory.CreateDbContextAsync(ct); await using var transaction = await db.Database.BeginTransactionAsync(ct); var s = await Aggregate(db, supplierId, ct); EnsureVersion(s.Version, r.ExpectedVersion); var c = s.Contacts.SingleOrDefault(x => x.Id == contactId) ?? throw new KeyNotFoundException(); if (!c.IsActive && r.IsPrimary) throw Validation("isPrimary", "مخاطب غیرفعال نمی‌تواند اصلی باشد."); if (r.IsPrimary) ClearPrimary(s, c.Id); c.Edit(r.FullName.Trim(), Clean(r.JobTitle), Clean(r.Email), Clean(r.Phone), Clean(r.Mobile), r.IsPrimary); await BumpAggregateVersion(db, s.Id, r.ExpectedVersion, ct); db.Entry(s).State = EntityState.Detached; await Save(db, ct); await transaction.CommitAsync(ct); var response = (await Load(db, s.Id, ct))!; await Emit("Supplier", s.Id, "CONTACT_EDIT", response, null, ct); return response; }
    public async Task<SupplierResponse> ContactState(Guid supplierId, Guid contactId, bool active, ChangeSupplierStateRequest r, CancellationToken ct) { await using var db = await factory.CreateDbContextAsync(ct); await using var transaction = await db.Database.BeginTransactionAsync(ct); var s = await Aggregate(db, supplierId, ct); EnsureVersion(s.Version, r.ExpectedVersion); var c = s.Contacts.SingleOrDefault(x => x.Id == contactId) ?? throw new KeyNotFoundException(); if (active) c.Reactivate(false); else c.Deactivate(); await BumpAggregateVersion(db, s.Id, r.ExpectedVersion, ct); db.Entry(s).State = EntityState.Detached; await Save(db, ct); await transaction.CommitAsync(ct); var response = (await Load(db, s.Id, ct))!; await Emit("Supplier", s.Id, active ? "CONTACT_REACTIVATE" : "CONTACT_DEACTIVATE", response, r.Reason, ct); return response; }

    private static void ClearPrimary(Supplier s, Guid? except = null) { foreach (var c in s.Contacts.Where(x => x.IsActive && x.IsPrimary && x.Id != except)) c.Edit(c.FullName, c.JobTitle, c.Email, c.Phone, c.Mobile, false); }
    private static async Task BumpAggregateVersion(HadronDbContext db, Guid id, long expected, CancellationToken ct) { var now = DateTime.UtcNow; var changed = await db.Suppliers.Where(x => x.Id == id && x.Version == expected).ExecuteUpdateAsync(setters => setters.SetProperty(x => x.Version, x => x.Version + 1).SetProperty(x => x.UpdatedAtUtc, now), ct); if (changed != 1) { var observed = await db.Suppliers.AsNoTracking().Where(x => x.Id == id).Select(x => x.Version).SingleOrDefaultAsync(ct); throw new SupplierConflictException("STALE_VERSION", "نسخه ارسالی قدیمی است.", new { ExpectedVersion = expected, ObservedVersion = observed }); } var tracked = db.ChangeTracker.Entries<Supplier>().SingleOrDefault(x => x.Entity.Id == id); if (tracked != null) { tracked.Property(x => x.Version).CurrentValue = expected + 1; tracked.Property(x => x.Version).OriginalValue = expected + 1; tracked.Property(x => x.UpdatedAtUtc).CurrentValue = now; tracked.Property(x => x.UpdatedAtUtc).OriginalValue = now; tracked.State = EntityState.Unchanged; } }
    private static async Task<Supplier> Aggregate(HadronDbContext db, Guid id, CancellationToken ct) => await db.Suppliers.Include(x => x.PaymentProfile).Include(x => x.Contacts).SingleOrDefaultAsync(x => x.Id == id, ct) ?? throw new KeyNotFoundException();
    private static async Task ValidateReferences(HadronDbContext db, Guid country, Guid? owner, Guid? term, bool checkCountry, bool checkOwner, bool checkTerm, bool requireAll, CancellationToken ct) { var errors = new Dictionary<string, string[]>(); if ((requireAll || checkCountry) && !await db.ReferenceValues.AnyAsync(x => x.Id == country && x.ReferenceType.Code == "COUNTRY" && x.IsActive, ct)) errors["countryId"] = ["کشور باید از نوع COUNTRY و فعال باشد."]; if ((requireAll || checkOwner) && (!owner.HasValue ? requireAll : !await db.InternalPeople.AnyAsync(x => x.Id == owner && x.IsActive, ct))) errors["ownerId"] = ["مالک فعال الزامی است."]; if ((requireAll || checkTerm) && (!term.HasValue ? requireAll : !await db.ReferenceValues.AnyAsync(x => x.Id == term && x.ReferenceType.Code == "PAYMENT_TERM" && x.IsActive, ct))) errors["paymentTermId"] = ["شرط پرداخت فعال الزامی است."]; if (errors.Count > 0) throw new SupplierValidationException(errors); }
    private static void ValidateSupplier(string name, decimal a, decimal b, decimal c, int? days, string? anchor, int? lead, int? quality, string? notes, long? version, bool activation) { var e = new Dictionary<string, string[]>(); if (string.IsNullOrWhiteSpace(name) || name.Trim().Length > 200) e["name"] = ["نام تأمین‌کننده الزامی و حداکثر ۲۰۰ نویسه است."]; if (a < 0 || a > 100 || b < 0 || b > 100 || c < 0 || c > 100) e["percentages"] = ["هر درصد باید بین ۰ و ۱۰۰ باشد."]; var normalized = NormalizeAnchor(anchor); if (c > 0 && (days is null or <= 0 || normalized is null || !Anchors.Contains(normalized))) e["credit"] = ["اعتبار مثبت به روز اعتبار مثبت و رویداد معتبر نیاز دارد."]; if (activation && a + b + c != 100m) e["paymentTotal"] = ["مجموع درصدهای پرداخت باید دقیقاً ۱۰۰٫۰۰ باشد."]; if (lead.HasValue && lead is < 1 or > 10) e["expertLeadTimeScore"] = ["امتیاز باید ۱ تا ۱۰ باشد."]; if (quality.HasValue && quality is < 1 or > 10) e["expertQualityScore"] = ["امتیاز باید ۱ تا ۱۰ باشد."]; if (Clean(notes)?.Length > 2000) e["notes"] = ["یادداشت حداکثر ۲۰۰۰ نویسه است."]; if (version.HasValue && version < 1) e["expectedVersion"] = ["نسخه معتبر الزامی است."]; if (e.Count > 0) throw new SupplierValidationException(e); }
    private static void ValidatePerson(string fa, string? en, long? version) { var e = new Dictionary<string, string[]>(); if (string.IsNullOrWhiteSpace(fa) || fa.Trim().Length > 200) e["displayNameFa"] = ["نام فارسی الزامی و حداکثر ۲۰۰ نویسه است."]; if (Clean(en)?.Length > 200) e["displayNameEn"] = ["نام انگلیسی حداکثر ۲۰۰ نویسه است."]; if (version.HasValue && version < 1) e["expectedVersion"] = ["نسخه معتبر الزامی است."]; if (e.Count > 0) throw new SupplierValidationException(e); }
    private static void ValidateContact(ContactRequest r) { var e = new Dictionary<string, string[]>(); if (string.IsNullOrWhiteSpace(r.FullName) || r.FullName.Trim().Length > 200) e["fullName"] = ["نام کامل الزامی و حداکثر ۲۰۰ نویسه است."]; if (Clean(r.JobTitle)?.Length > 150) e["jobTitle"] = ["سمت حداکثر ۱۵۰ نویسه است."]; if (Clean(r.Email)?.Length > 254) e["email"] = ["ایمیل حداکثر ۲۵۴ نویسه است."]; if (r.ExpectedVersion < 1) e["expectedVersion"] = ["نسخه معتبر الزامی است."]; if (e.Count > 0) throw new SupplierValidationException(e); }
    private static async Task<SupplierResponse?> Load(HadronDbContext db, Guid id, CancellationToken ct) { var s = await db.Suppliers.AsNoTracking().Include(x => x.Country).Include(x => x.Owner).Include(x => x.PaymentProfile).ThenInclude(x => x.PaymentTerm).Include(x => x.Contacts).SingleOrDefaultAsync(x => x.Id == id, ct); return s == null ? null : ToResponse(s, s.Contacts.OrderByDescending(x => x.IsPrimary).ThenBy(x => x.FullName).Select(x => new ContactResponse(x.Id, x.FullName, x.JobTitle, x.Email, x.Phone, x.Mobile, x.IsPrimary, x.IsActive, x.CreatedAtUtc, x.UpdatedAtUtc)).ToList()); }
    private static SupplierResponse ToResponse(Supplier s, IReadOnlyList<ContactResponse> contacts) => new(s.Id, s.SupplierNumber, s.Name, Ref(s.Country), s.Owner == null ? null : ToPerson(s.Owner), new(s.PaymentProfile.PaymentTermId, s.PaymentProfile.PaymentTerm == null ? null : Ref(s.PaymentProfile.PaymentTerm), s.PaymentProfile.AdvancePercent, s.PaymentProfile.BeforeShipmentPercent, s.PaymentProfile.CreditPercent, s.PaymentProfile.CreditDays, s.PaymentProfile.CreditAnchor), s.ExpertLeadTimeScore, s.ExpertQualityScore, s.Notes, s.IsActive, s.Version, s.CreatedAtUtc, s.UpdatedAtUtc, contacts);
    private static SupplierRef Ref(Modules.ReferenceData.Domain.ReferenceValue x) => new(x.Id, x.Code, x.NameFa, x.NameEn, x.IsActive); private static PersonResponse ToPerson(InternalPerson x) => new(x.Id, x.DisplayNameFa, x.DisplayNameEn, x.IsActive, x.Version, x.CreatedAtUtc, x.UpdatedAtUtc);
    private static async Task<string> NextNumber(HadronDbContext db, CancellationToken ct) { var connection = (NpgsqlConnection)db.Database.GetDbConnection(); if (connection.State != System.Data.ConnectionState.Open) await connection.OpenAsync(ct); await using var cmd = new NpgsqlCommand("SELECT nextval('procurement.supplier_number_seq')", connection); var value = (long)(await cmd.ExecuteScalarAsync(ct))!; return $"SUP-{value:D4}"; }
    private static async Task<IReadOnlyList<string>> Warnings(HadronDbContext db, Guid id, string name, CancellationToken ct) => await db.Suppliers.AnyAsync(x => x.Id != id && x.NormalizedName == NormalizeName(name), ct) ? ["DUPLICATE_SUPPLIER_NAME"] : [];
    private static async Task Save(HadronDbContext db, CancellationToken ct) { try { await db.SaveChangesAsync(ct); } catch (DbUpdateConcurrencyException) { throw new SupplierConflictException("STALE_VERSION", "نسخه ارسالی قدیمی است."); } catch (DbUpdateException ex) when (ex.InnerException is PostgresException { SqlState: PostgresErrorCodes.UniqueViolation }) { throw new SupplierConflictException("SUPPLIER_INTEGRITY_CONFLICT", "تعارض یکتایی داده تأمین‌کننده."); } }
    private async Task Emit(string type, Guid id, string action, object value, string? reason, CancellationToken ct) { try { await auditSink.WriteAsync(new(type, id, action, DateTime.UtcNow, AuditEventContext.ActorId(accessor.HttpContext), AuditEventContext.CorrelationId(accessor.HttpContext), null, new Dictionary<string, object?> { { "Value", value } }, reason), ct); } catch (OperationCanceledException) when (ct.IsCancellationRequested) { throw; } catch (Exception ex) { logger.LogError(ex, "Post-commit supplier audit failed for {Id} {Action}", id, action); } }
    private static void EnsureVersion(long actual, long expected) { if (actual != expected) throw new SupplierConflictException("STALE_VERSION", "نسخه ارسالی قدیمی است.", new { ActualVersion = actual, ExpectedVersion = expected }); }
    private static string NormalizeName(string s) => s.Trim().ToUpperInvariant(); private static string? NormalizeAnchor(string? s) => Clean(s)?.ToUpperInvariant(); private static string? Clean(string? s) => string.IsNullOrWhiteSpace(s) ? null : s.Trim(); private static SupplierValidationException Validation(string k, string m) => new(new Dictionary<string, string[]> { { k, [m] } });
}
